INSERT INTO portfolio_projects(id,slug,title,summary,description,category,kind,project_url,technologies,featured,sort_order) VALUES('prj_venora-jewelry','venora-jewelry','VENORA JEWELRY','An ecommerce jewellery storefront concept with product collections, product variations, separate pricing and imagery for variants, and WhatsApp ordering.','VENORA JEWELRY is an internal Noorix project and a concept storefront, not a paid client project.
INSERT INTO portfolio_projects(id,slug,title,summary,description,category,kind,project_url,technologies,featured,sort_order) VALUES('prj_nexus-pro-smm','nexus-pro-smm','NEXUS PRO SMM','A social media marketing services platform with service ordering and customer-facing account functionality.','NEXUS PRO SMM is an internal Noorix project: a web platform for social media marketing services with service ordering and customer-facing account functionality.
INSERT INTO faqs(id,question,answer,sort_order) VALUES('faq_01','What services does Noorix Digital Lab offer?','We offer website development, ecommerce development, social media management, AI chatbots, business automation, and hosting, maintenance and technical support.',0);
INSERT INTO faqs(id,question,answer,sort_order) VALUES('faq_02','Do you work with international clients?','Yes. We work with clients in Pakistan and internationally. Prices are listed in USD by default, and we can provide a quote in PKR for the Pakistan market.',1);
INSERT INTO faqs(id,question,answer,sort_order) VALUES('faq_03','How long does website development take?','It depends on the number of pages, features and how quickly content and feedback are provided. We share an estimated timeline in the proposal after understanding your requirements.',2);
INSERT INTO faqs(id,question,answer,sort_order) VALUES('faq_04','Can you redesign an existing website?','Yes. We can redesign an existing website to improve its look, structure and performance. Tell us about your current site when you contact us.',3);
INSERT INTO faqs(id,question,answer,sort_order) VALUES('faq_05','Do you provide ecommerce development?','Yes. We build online stores with product management, categories, variations, cart and checkout, order management and an admin dashboard. Payment gateway availability depends on the provider and your requirements.',4);
INSERT INTO faqs(id,question,answer,sort_order) VALUES('faq_06','Do you manage social media accounts?','Yes. Our social media management includes strategy, content calendars, branded post designs, captions, scheduling, account management and monthly reporting. We do not guarantee specific follower, view or sales numbers.',5);
INSERT INTO faqs(id,question,answer,sort_order) VALUES('faq_07','Can you build AI chatbots?','Yes. We set up business-specific chatbots that answer common questions, collect lead details and can hand over to a human where configured.',6);
INSERT INTO faqs(id,question,answer,sort_order) VALUES('faq_08','Do you provide maintenance?','Yes. Our hosting and maintenance plans cover updates, backups, troubleshooting and performance checks, billed monthly.',7);
INSERT INTO faqs(id,question,answer,sort_order) VALUES('faq_09','Are hosting and third-party subscriptions included?','Not unless a proposal says so. Domains, hosting, paid APIs, AI usage fees, advertising budgets and other third-party subscriptions are separate costs.',8);
INSERT INTO faqs(id,question,answer,sort_order) VALUES('faq_10','How can I start a project?','Send us a message through the contact form or WhatsApp with a short description of what you need. We will reply to discuss scope, timeline and a quote.',9);
